userscript.function:

if (gridObj && gridObj.destructor) {
    Sepoa.detachEvent('onLoad', events.onLoad);
    SUX.detachEvent('onWindowResize', events.resize);
    events = {};
    gridObj.destructor();
}

gridObj = $sObject.gridObj = new SepoaDhtmlXGridObject(gridbox, 'gridObj', obj);
gridObj._onDnDFlag = false;
gridObj.setGridDraw();
gridObj.setSizes();
gridObj.setEditable(false);
gridObj.setDataOutput(dataOutput);
gridObj.attachEvent('onMouseOver', parentGridEditStop);
events.onLoad = Sepoa.attachEvent('onLoad', function() {
    gridObj.setSizes();
});
events.resize = SUX.attachEvent('onWindowResize', function() {
    gridObj.setSizes();
});

createDummyRow(obj);


if (gridObj && gridObj.destructor) {
    Sepoa.detachEvent('onLoad', events.onLoad);
    SUX.detachEvent('onWindowResize', events.resize);
    events = {};
    gridObj.destructor();
}

gridObj = $sObject.gridObj = new SepoaDhtmlXGridObject(gridbox, 'gridObj');
gridObj._onDnDFlag = false;
gridObj.setGridDraw();
gridObj.setSizes();
gridObj.setEditable(false);
gridObj.attachEvent('onMouseOver', parentGridEditStop);

var cin = 0;

for (var i = 0; i < obj.length; i++) {

    if (obj[i].COL_VISIBLE == 'false') continue;

    var header = obj[i].CONTENTS_KO;
    var type = obj[i].COL_TYPE;
    var width = obj[i].COL_WIDTH_KO;
    var align = obj[i].COL_ALIGN;

    cin++;

    if (['tree', 'grid', 'template', 'comboro', 'comboro2'].indexOf(type) + 1) {
        type = 'edtxt';
    }

    gridObj.insertColumn(cin, header, type, width, null, align, null, null, null);
}

createDummyRow(obj);


var rId = dhx.newId();
var columnIndexer = 0;
gridObj.addRow(rId, '', 0);

for (var i in obj) {
    var item = integerParser(i);
    var type = obj[item].COL_TYPE;

    if (obj[item].COL_VISIBLE == 'false') continue;

    var cId = columnIndexParser(gridObj.getColIndexById(obj[item].CODE), columnIndexer);

    if (['ch'].indexOf(type) + 1) {
        gridObj.cells(rId, cId).setValue('0');
    } else if (['dhxCalendar', 'dhxCalendarA', 'dhxCalendarR'].indexOf(type) + 1) {
        gridObj.cells(rId, cId).setValue(sUtils.date.getToday());
    } else if (['dhxCalendarYM', 'dhxCalendarYMR'].indexOf(type) + 1) {
        gridObj.cells(rId, cId).setValue(Sepoa.calendar.YM);
    } else if (['edn', 'ron'].indexOf(type) + 1) {
        gridObj.cells(rId, cId).setValue('12345.6789');
    } else if (['edtxt', 'txttxt', 'ro', 'rotxt', 'tree', 'template'].indexOf(type) + 1) {
        gridObj.cells(rId, cId).setValue(type.toUpperCase());
    }

    columnIndexer++;
}


var parsed = parseInt(x);
if (isNaN(parsed)) {
    return x;
}
return parsed;


var retValue = col;
if (col === undefined) {
    return parseInt(index);
}
return col;
